// 平台 N8nWorkflowProvider POST 過嚟嘅 body（CONTRACT-OUTBOUND §3）
// { targetUpn, opcoCode, requesterEmail, remark, lineItems:[{skuId, skuPartNumber, quantity}] }
const body = $input.first().json.body || {};
const lines = (body.lineItems || []).map((l, i) => ({
  skuId: l.skuId,                              // 必須對回 payload 次序（平台會核對）
  sysId: 'RITM-mock-' + Date.now() + '-' + i,  // mock sc_req_item sysId
  number: 'RITM' + (1000 + i)
}));
// 回 CONTRACT-OUTBOUND §4 格式（平台 fail-closed 會查 request.sysId + 每 line sysId + skuId 對次序）
return [{ json: {
  request: { sysId: 'REQ-mock-' + Date.now(), number: 'REQ-N8N-TEST' },
  lineItems: lines
} }];
